class DeviceBootError extends TaggedError3()("DeviceBootError", {
  hostId: DeviceHostId,
  deviceId: DeviceId,
  reason: Literals(["disk_space", "timeout", "launch_failed"]),
  diagnostics: optional2(String6.check(isMaxLength(2000))),
  cause: Defect()
}) {
  get message() {
    const explanation = {
      disk_space: "There is not enough free disk space on its device host.",
      timeout: "The device did not become ready in time.",
      launch_failed: "The simulator or emulator could not start."
    }[this.reason];
    const summary = `Device ${this.deviceId} failed to boot: ${explanation}`;
    return this.diagnostics ? `${summary}

${this.diagnostics}` : `${summary} The device host sent no details. Try again or open another device; if it keeps failing, check the device on that host.`;
  }
}

class DeviceOperationError extends TaggedError3()("DeviceOperationError", {
  operation: String6,
  reason: Literals([
    "command_failed",
    "request_failed",
    "invalid_payload",
    "settings_failed",
    "hub_rejected"
  ]),
  exitCode: optional2(Number6),
  cause: Defect()
}) {
  get message() {
    const explanation = {
      command_failed: `The device command failed${this.exitCode === undefined ? "" : ` (exit code ${this.exitCode})`}.`,
      request_failed: "Could not communicate with device support. Try refreshing devices.",
      invalid_payload: "The device request could not be encoded.",
      settings_failed: "Could not read or save device settings.",
      hub_rejected: "The device hub could not complete the request."
    }[this.reason];
    return `Device ${this.operation} failed: ${explanation}`;
  }
}

