class PreviewStopLocalServerError extends exports_Schema.TaggedError()("PreviewStopLocalServerError", {
  reason: exports_Schema.Literals(["not-found", "shared-group", "unsupported", "signal-failed"]),
  cause: exports_Schema.optional(exports_Schema.Defect())
}) {
  get message() {
    switch (this.reason) {
      case "not-found":
        return "This server is no longer running.";
      case "shared-group":
        return "This server shares a process group with T3 Code, an agent, or a terminal shell, so it can't be stopped on its own.";
      case "unsupported":
        return "Stopping servers is not supported on this environment's platform.";
      case "signal-failed":
        return "The server's processes could not be signaled.";
    }
  }
}
